using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class Stodmarsh : LayoutBase
{
    public Stodmarsh()
    {
        Name = LayoutNamesEnums.Stodmarsh;
        Owner = "The Gauge O Guild";
        Description = "Stodmarsh combines railway modelling with a military theme by recreating the East Kent Railway in southern England during the Second World War. This 7mm:1ft layout is based on a proposed but never completed extension to the East Kent Railway - owned by Colonel Stephens, the line would have run from Wingham to Canterbury West via Stodmarsh, some seven and a half miles. Construction began at Wingham in 1919 but was cancelled in 1931 owing to the General Strike, the Depression and the untimely death of the Colonel. The layout's fictional history sees construction terminate at Stodmarsh due to financial pressure and declining traffic, with the Southern Railway closing the line in 1940 and being forced to reopen it three years later to help move men, munitions and machinery to the south coast embarkation ports in preparation for D-Day. Visitors join the layout on a day of total chaos, with British and American forces on manoeuvres, residents running for cover from Luftwaffe incendiaries, the National Fire Service damping down a grass fire and the Home Guard capturing a shot down German airman - and occasionally, amid the melee, a train working in the station.";
    }
}
